type DCNetLabHTTPClient interface {
	ApplyFaultScenario(ctx context.Context, req *FaultScenarioOpRequest, opts ...http.CallOption) (rsp *FaultScenario, err error)
	ApplyPlan(ctx context.Context, req *ApplyPlanRequest, opts ...http.CallOption) (rsp *OperationRef, err error)
	// BatchProgramOp BatchProgramOp starts, stops or deletes several programs at once
	// (op is start|stop|delete); each id is applied best-effort and its
	// outcome is reported, so one failure does not abort the rest.
	BatchProgramOp(ctx context.Context, req *BatchProgramRequest, opts ...http.CallOption) (rsp *BatchProgramReply, err error)
	// CreateCaptureSession --- Capture ---
	// CaptureSessions record packets on one modelled interface of a lab
	// node (a topology link endpoint or vlanif/bond0) into a pcapng
	// file, with per-packet metadata available live. A session starts
	// capturing on creation and ends by itself (duration or limit) or
	// via stop; the recording stays downloadable until the session is
	// deleted or expires. The pcapng download is a plain HTTP route
	// (GET /api/v1/labs/{lab_id}/captures/{id}/pcap) and live metadata
	// is also pushed on WS /ws/v1/captures/{id}.
	CreateCaptureSession(ctx context.Context, req *CreateCaptureSessionRequest, opts ...http.CallOption) (rsp *CaptureSession, err error)
	// CreateFaultScenario --- Fault ---
	// FaultScenarios inject and recover a controlled failure against a
	// node or a link: node-stop/node-restart reuse the same pause/
	// unpause power semantics as the topology page; link-down and
	// interface-down set the interface administratively down; impairment
	// shapes egress traffic with one netem qdisc (delay/jitter/loss/rate
	// combined, matching how netem itself works — there is only ever one
	// qdisc per interface). A target (node or link) allows at most one
	// applied scenario at a time.
	CreateFaultScenario(ctx context.Context, req *CreateFaultScenarioRequest, opts ...http.CallOption) (rsp *FaultScenario, err error)
	// CreateLab --- Labs ---
	CreateLab(ctx context.Context, req *CreateLabRequest, opts ...http.CallOption) (rsp *Lab, err error)
	// CreatePlan --- Plans ---
	CreatePlan(ctx context.Context, req *CreatePlanRequest, opts ...http.CallOption) (rsp *Plan, err error)
	// CreateProgram --- Programs ---
	// Programs are supervised processes on lab servers, each running
	// the entrypoint of an installed Package version, managed through
	// the per-server dcnetlab-server-agent.
	CreateProgram(ctx context.Context, req *CreateProgramRequest, opts ...http.CallOption) (rsp *CreateProgramReply, err error)
	// CreateTrafficScenario --- Traffic ---
	// TrafficScenarios drive measurable traffic between two lab servers
	// through a pair of trafficgen Programs (server role on the
	// destination, client role on the source); the collector tails the
	// client's stat lines into rate/success-rate/latency metrics and
	// evaluates any configured assertions.
	CreateTrafficScenario(ctx context.Context, req *CreateTrafficScenarioRequest, opts ...http.CallOption) (rsp *TrafficScenario, err error)
	DeleteCaptureSession(ctx context.Context, req *CaptureSessionOpRequest, opts ...http.CallOption) (rsp *DeleteCaptureSessionReply, err error)
	DeleteFaultScenario(ctx context.Context, req *FaultScenarioOpRequest, opts ...http.CallOption) (rsp *DeleteFaultScenarioReply, err error)
	DeleteLab(ctx context.Context, req *DeleteLabRequest, opts ...http.CallOption) (rsp *OperationRef, err error)
	DeletePackage(ctx context.Context, req *DeletePackageRequest, opts ...http.CallOption) (rsp *DeletePackageReply, err error)
	DeleteProgram(ctx context.Context, req *ProgramOpRequest, opts ...http.CallOption) (rsp *DeleteProgramReply, err error)
	DeleteTrafficScenario(ctx context.Context, req *TrafficScenarioOpRequest, opts ...http.CallOption) (rsp *DeleteTrafficScenarioReply, err error)
	GetCapturePacket(ctx context.Context, req *GetCapturePacketRequest, opts ...http.CallOption) (rsp *CapturePacketDetail, err error)
	GetCaptureSession(ctx context.Context, req *CaptureSessionOpRequest, opts ...http.CallOption) (rsp *CaptureSession, err error)
	GetLab(ctx context.Context, req *GetLabRequest, opts ...http.CallOption) (rsp *Lab, err error)
	// GetNodeBGP GetNodeBGP returns the BGP configuration of one node as derived
	// by the FRR compiler from the topology model: eBGP neighbors over
	// fabric links, the MLAG iBGP session and the leaf's dynamic server
	// peer-group. Empty for nodes that do not run BGP.
	GetNodeBGP(ctx context.Context, req *GetNodeBGPRequest, opts ...http.CallOption) (rsp *NodeBGP, err error)
	// GetNodeBGPTable GetNodeBGPTable returns the live BGP Loc-RIB of one deployed
	// node (`show ip bgp`): every candidate path per prefix, before
	// best-path selection reduces them to the RIB entry.
	GetNodeBGPTable(ctx context.Context, req *GetNodeBGPTableRequest, opts ...http.CallOption) (rsp *NodeBGPTable, err error)
	// GetNodeFIB GetNodeFIB returns the live kernel forwarding table of one
	// deployed node (`ip route`): what actually forwards packets, as
	// installed by zebra from the RIB.
	GetNodeFIB(ctx context.Context, req *GetNodeFIBRequest, opts ...http.CallOption) (rsp *NodeFIB, err error)
	// GetNodeInventory GetNodeInventory reports what is actually on one server, live
	// from its agent: installed package versions and every program
	// (controller-managed or created node-locally via the in-container
	// CLI).
	GetNodeInventory(ctx context.Context, req *GetNodeInventoryRequest, opts ...http.CallOption) (rsp *NodeInventory, err error)
	// GetNodeMetrics GetNodeMetrics samples resource usage of one server live from
	// its agent, node-exporter style: CPU, memory, load, filesystem,
	// disk I/O and per-interface network.
	GetNodeMetrics(ctx context.Context, req *GetNodeMetricsRequest, opts ...http.CallOption) (rsp *NodeMetrics, err error)
	// GetNodeMetricsHistory GetNodeMetricsHistory returns the collected resource-usage time
	// series of one server: 15 s points from the controller's metrics
	// collector, kept 2 h in memory and 24 h on disk.
	GetNodeMetricsHistory(ctx context.Context, req *GetNodeMetricsHistoryRequest, opts ...http.CallOption) (rsp *NodeMetricsHistory, err error)
	// GetNodeRoutes GetNodeRoutes returns the live IPv4 routing table (FRR RIB) of
	// one deployed node; routes are empty unless the container is
	// running.
	GetNodeRoutes(ctx context.Context, req *GetNodeRoutesRequest, opts ...http.CallOption) (rsp *NodeRoutes, err error)
	// GetNodeRuntime GetNodeRuntime returns the management view of one deployed node:
	// the underlying container state and every kernel interface inside
	// it, including implementation plumbing (bridge, VRRP macvlan,
	// management eth0) that the simulated topology does not model.
	GetNodeRuntime(ctx context.Context, req *GetNodeRuntimeRequest, opts ...http.CallOption) (rsp *NodeRuntime, err error)
	// GetOperation --- Operations & Generations ---
	GetOperation(ctx context.Context, req *GetOperationRequest, opts ...http.CallOption) (rsp *Operation, err error)
	GetPlan(ctx context.Context, req *GetPlanRequest, opts ...http.CallOption) (rsp *Plan, err error)
	GetProgramLogs(ctx context.Context, req *GetProgramLogsRequest, opts ...http.CallOption) (rsp *ProgramLogs, err error)
	// GetTrafficScenarioHistory GetTrafficScenarioHistory returns the collected metrics series of
	// one scenario: 5 s points kept in memory for up to one hour
	// (scenarios are short interactive experiments, not persisted
	// across a controller restart like server metrics).
	GetTrafficScenarioHistory(ctx context.Context, req *GetTrafficScenarioHistoryRequest, opts ...http.CallOption) (rsp *TrafficScenarioHistory, err error)
	Healthz(ctx context.Context, req *HealthzRequest, opts ...http.CallOption) (rsp *HealthzReply, err error)
	// InstallPackage InstallPackage delivers a package version onto lab servers
	// without declaring a program — the "deploy a binary" path (apt
	// install without a service unit). Idempotent per server: agents
	// skip versions already present with the same digest.
	InstallPackage(ctx context.Context, req *InstallPackageRequest, opts ...http.CallOption) (rsp *InstallPackageReply, err error)
	ListAllocations(ctx context.Context, req *ListAllocationsRequest, opts ...http.CallOption) (rsp *ListAllocationsReply, err error)
	ListCapturePackets(ctx context.Context, req *ListCapturePacketsRequest, opts ...http.CallOption) (rsp *ListCapturePacketsReply, err error)
	ListCaptureSessions(ctx context.Context, req *ListCaptureSessionsRequest, opts ...http.CallOption) (rsp *ListCaptureSessionsReply, err error)
	ListFaultScenarios(ctx context.Context, req *ListFaultScenariosRequest, opts ...http.CallOption) (rsp *ListFaultScenariosReply, err error)
	ListGenerations(ctx context.Context, req *ListGenerationsRequest, opts ...http.CallOption) (rsp *ListGenerationsReply, err error)
	ListLabs(ctx context.Context, req *ListLabsRequest, opts ...http.CallOption) (rsp *ListLabsReply, err error)
	ListLinks(ctx context.Context, req *ListLinksRequest, opts ...http.CallOption) (rsp *ListLinksReply, err error)
	// ListNodes --- Topology ---
	ListNodes(ctx context.Context, req *ListNodesRequest, opts ...http.CallOption) (rsp *ListNodesReply, err error)
	ListOperations(ctx context.Context, req *ListOperationsRequest, opts ...http.CallOption) (rsp *ListOperationsReply, err error)
	ListPackages(ctx context.Context, req *ListPackagesRequest, opts ...http.CallOption) (rsp *ListPackagesReply, err error)
	// ListProfiles --- Profiles & health ---
	ListProfiles(ctx context.Context, req *ListProfilesRequest, opts ...http.CallOption) (rsp *ListProfilesReply, err error)
	ListPrograms(ctx context.Context, req *ListProgramsRequest, opts ...http.CallOption) (rsp *ListProgramsReply, err error)
	ListTrafficScenarios(ctx context.Context, req *ListTrafficScenariosRequest, opts ...http.CallOption) (rsp *ListTrafficScenariosReply, err error)
	RecoverFaultScenario(ctx context.Context, req *FaultScenarioOpRequest, opts ...http.CallOption) (rsp *FaultScenario, err error)
	// RepairLab RepairLab re-attaches any simulated interfaces the runtime lost
	// (e.g. a host Docker daemon restart dropping veth pairs) without
	// going through Plan/Apply: it re-runs the same idempotent deploy
	// against the lab's current generation, so already-running
	// containers and their programs are left untouched.
	RepairLab(ctx context.Context, req *RepairLabRequest, opts ...http.CallOption) (rsp *OperationRef, err error)
	// StartLab StartLab / StopLab power the deployed containers of a lab on and
	// off (docker start/stop) without touching the generation.
	StartLab(ctx context.Context, req *StartLabRequest, opts ...http.CallOption) (rsp *OperationRef, err error)
	// StartNode StartNode / StopNode power a single device on and off.
	StartNode(ctx context.Context, req *StartNodeRequest, opts ...http.CallOption) (rsp *Node, err error)
	StartProgram(ctx context.Context, req *ProgramOpRequest, opts ...http.CallOption) (rsp *Program, err error)
	StartTrafficScenario(ctx context.Context, req *TrafficScenarioOpRequest, opts ...http.CallOption) (rsp *TrafficScenario, err error)
	StopCaptureSession(ctx context.Context, req *CaptureSessionOpRequest, opts ...http.CallOption) (rsp *CaptureSession, err error)
	StopLab(ctx context.Context, req *StopLabRequest, opts ...http.CallOption) (rsp *OperationRef, err error)
	StopNode(ctx context.Context, req *StopNodeRequest, opts ...http.CallOption) (rsp *Node, err error)
	StopProgram(ctx context.Context, req *ProgramOpRequest, opts ...http.CallOption) (rsp *Program, err error)
	StopTrafficScenario(ctx context.Context, req *TrafficScenarioOpRequest, opts ...http.CallOption) (rsp *TrafficScenario, err error)
	UpgradeProgram(ctx context.Context, req *UpgradeProgramRequest, opts ...http.CallOption) (rsp *Program, err error)
	// UploadPackage --- Packages ---
	// Packages are versioned program artifacts (tar.gz with a
	// manifest.json) in the controller's repository; lab servers
	// install them through their agent. The bundled lab-app registers
	// as the builtin package; uploads use the same pipeline.
	UploadPackage(ctx context.Context, req *UploadPackageRequest, opts ...http.CallOption) (rsp *Package, err error)
}

